<?php require 'config/config.php';auth();if(user()['role']!=='owner')go(BASE_URL.'/dashboard.php');if($_POST){check();db()->beginTransaction();db()->prepare('INSERT INTO properties(owner_id,title,address,city,description) VALUES(?,?,?,?,?)')->execute([user()['id'],$_POST['title'],$_POST['address'],$_POST['city'],$_POST['description']]);$pid=db()->lastInsertId();db()->prepare('INSERT INTO rooms(property_id,room_number,room_type,rent,deposit,status) VALUES(?,?,?,?,?,?)')->execute([$pid,$_POST['room_number'],$_POST['room_type'],$_POST['rent'],$_POST['deposit'],'available']);db()->commit();go(BASE_URL.'/owner.php');}$title='Owner';require 'config/header.php';?><div class="auth"><div class="panel"><small>OWNER PANEL</small><h1>List a room</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Property title<input name="title" required></label><label>Address<input name="address" required></label><label>City<input name="city" required></label><label>Description<textarea name="description"></textarea></label><label>Room number<input name="room_number" required></label><label>Room type<select name="room_type"><option>private</option><option>shared</option></select></label><label>Monthly rent<input type="number" name="rent" required></label><label>Advance/deposit<input type="number" name="deposit" required></label><button class="btn">Publish Room</button></form></div></div><?php require 'config/footer.php';?>
